match parser.parse_drop_table_stmt() {
        Ok(stmt) => match parser.expect_end() {
            Ok(()) => ParseOutcome::Accepted(Box::new(stmt)),
            Err(ParseFail::Unsupported { message, span }) => {
                ParseOutcome::Unsupported { message, span }
