                pattern,
                glob,
                negated,
                escape,
            } => {
                let op = if *glob { "GLOB" } else { "LIKE" };
                write!(
                    f,
                    "{expr} {}{op} {pattern}",
                    if *negated { "NOT " } else { "" }
