                                Some('*') => {
                                    self.bump(src);
                                    if self.peek_char(src) == Some('/') {
                                        self.bump(src);
                                        break;
                                    }
                                }
                                Some(_) => {
                                    self.bump(src);
                                }
                            }
                        }
                        continue;
                    }
