            }
            '\'' => self.scan_string(src),
            '"' => self.scan_quoted_identifier(src, '"', '"'),
            '[' => self.scan_quoted_identifier(src, '[', ']'),
            '`' => self.scan_quoted_identifier(src, '`', '`'),
            '?' => self.scan_param_question(src),
            ':' => self.scan_param_named(src, ':'),
            '@' => self.scan_param_named(src, '@'),
            '$' => self.scan_param_named(src, '$'),
            c if c == 'x' || c == 'X' => self.scan_maybe_blob(src, c),
            c if is_ident_start(c) => self.scan_identifier_or_keyword(src),
            _ => self.scan_operator(src),
        }

match self.peek_char(src) {
                    None => {
                        return TokenKind::Error(format!(
                            "unterminated blob literal starting with {x}'"
                        ));
                    }
                    Some('\'') => {
                        break;
                    }
                    Some(_) => {
                        self.bump(src);
                    }
                }

match u8::from_str_radix(pair, 16) {
                    Ok(b) => bytes.push(b),
                    Err(_) => {
                        let msg = format!("invalid blob byte: {pair:?}");
                        self.bump(src); // closing '
                        return TokenKind::Error(msg);
                    }
                }

match self.peek_char(src) {
                None => return TokenKind::Error("unterminated string literal".to_string()),
                Some('\'') => {
                    let quote_pos = self.pos;
                    self.bump(src); // consume this quote
                    if self.peek_char(src) == Some('\'') {
                        let seg = src.get(seg_start..quote_pos).unwrap_or("");
                        let buf = acc.get_or_insert_with(String::new);
                        buf.push_str(seg);
                        buf.push('\'');
                        self.bump(src); // consume the second quote
                        seg_start = self.pos;
                    } else {
                        let seg = src.get(seg_start..quote_pos).unwrap_or("");
                        return TokenKind::String(match acc {
                            Some(mut buf) => {
                                buf.push_str(seg);
                                buf
                            }
                            None => seg.to_string(),
                        });
                    }
                }
                Some(_) => {
                    self.bump(src);
                }
            }

match acc {
                            Some(mut buf) => {
                                buf.push_str(seg);
                                buf
                            }
                            None => seg.to_string(),
                        }

match self.peek_char(src) {
                None => {
                    return TokenKind::Error(format!(
                        "unterminated quoted identifier starting with {open:?}"
                    ));
                }
                Some(c) if c == close => {
                    let close_pos = self.pos;
                    self.bump(src); // consume this closing delimiter
                    if escapes && self.peek_char(src) == Some(close) {
                        let seg = src.get(seg_start..close_pos).unwrap_or("");
                        let buf = acc.get_or_insert_with(String::new);
                        buf.push_str(seg);
                        buf.push(close);
                        self.bump(src); // consume the doubled delimiter
                        seg_start = self.pos;
                    } else {
                        let seg = src.get(seg_start..close_pos).unwrap_or("");
                        return TokenKind::Identifier(match acc {
                            Some(mut buf) => {
                                buf.push_str(seg);
                                buf
                            }
                            None => seg.to_string(),
                        });
                    }
                }
                Some(_) => {
                    self.bump(src);
                }
            }

match acc {
                            Some(mut buf) => {
                                buf.push_str(seg);
                                buf
                            }
                            None => seg.to_string(),
                        }

match digits.parse::<u32>() {
                Ok(n) => TokenKind::Param(Box::new(Param::Numbered(n))),
                Err(_) => TokenKind::Error(format!("parameter number out of range: {digits}")),
            }

match i64::from_str_radix(hex, 16) {
                Ok(n) => TokenKind::Integer(n),
                Err(_) => match u64::from_str_radix(hex, 16) {
                    Ok(n) => TokenKind::Integer(n as i64),
                    Err(e) => TokenKind::Error(format!("invalid hex literal: {e}")),
                },
            }

match u64::from_str_radix(hex, 16) {
                    Ok(n) => TokenKind::Integer(n as i64),
                    Err(e) => TokenKind::Error(format!("invalid hex literal: {e}")),
                }

match text.parse::<f64>() {
                Ok(f) => TokenKind::Float(f),
                Err(e) => TokenKind::Error(format!("invalid float literal {text:?}: {e}")),
            }

match text.parse::<i64>() {
                Ok(n) => TokenKind::Integer(n),
                Err(_) => match text.parse::<f64>() {
                    Ok(f) => TokenKind::Float(f),
                    Err(e) => TokenKind::Error(format!("invalid integer literal {text:?}: {e}")),
                },
            }

match text.parse::<f64>() {
                    Ok(f) => TokenKind::Float(f),
                    Err(e) => TokenKind::Error(format!("invalid integer literal {text:?}: {e}")),
                }

match self.bump(src) {
            Some(c) => c,
            None => return TokenKind::Eof,
        }

match c {
            '*' => TokenKind::Star,
            ',' => TokenKind::Comma,
            ';' => TokenKind::Semicolon,
            '(' => TokenKind::LParen,
            ')' => TokenKind::RParen,
            '+' => TokenKind::Plus,
            '/' => TokenKind::Slash,
            '%' => TokenKind::Percent,
            '~' => TokenKind::BitNot,
            '-' => {
                if self.peek_char(src) == Some('>') {
                    self.bump(src);
                    if self.peek_char(src) == Some('>') {
                        self.bump(src);
                        TokenKind::ArrowArrow
                    } else {
                        TokenKind::Arrow
                    }
                } else {
                    TokenKind::Minus
                }
            }
            '=' => {
                if self.peek_char(src) == Some('=') {
                    self.bump(src);
                }
                TokenKind::Eq
            }
            '!' => {
                if self.peek_char(src) == Some('=') {
                    self.bump(src);
                    TokenKind::Ne
                } else {
                    TokenKind::Error("expected '=' after '!'".to_string())
                }
            }
            '<' => match self.peek_char(src) {
                Some('=') => {
                    self.bump(src);
                    TokenKind::Le
                }
                Some('>') => {
                    self.bump(src);
                    TokenKind::Ne
                }
                Some('<') => {
                    self.bump(src);
                    TokenKind::Shl
                }
                _ => TokenKind::Lt,
            },
            '>' => match self.peek_char(src) {
                Some('=') => {
                    self.bump(src);
                    TokenKind::Ge
                }
                Some('>') => {
                    self.bump(src);
                    TokenKind::Shr
                }
                _ => TokenKind::Gt,
            },
            '|' => {
                if self.peek_char(src) == Some('|') {
                    self.bump(src);
                    TokenKind::Concat
                } else {
                    TokenKind::BitOr
                }
            }
            '&' => TokenKind::BitAnd,
            other => TokenKind::Error(format!("unexpected character {other:?}")),
        }

match self.peek_char(src) {
                Some('=') => {
                    self.bump(src);
                    TokenKind::Le
                }
                Some('>') => {
                    self.bump(src);
                    TokenKind::Ne
                }
                Some('<') => {
                    self.bump(src);
                    TokenKind::Shl
                }
                _ => TokenKind::Lt,
            }

match self.peek_char(src) {
                Some('=') => {
                    self.bump(src);
                    TokenKind::Ge
                }
                Some('>') => {
                    self.bump(src);
                    TokenKind::Shr
                }
                _ => TokenKind::Gt,
            }

match tok.kind {
            TokenKind::Semicolon => {
                let end = tok.span.offset as usize;
                push_trimmed(&mut statements, sql.get(start..end).unwrap_or(""));
                start = (tok.span.offset as usize).saturating_add(tok.span.len as usize);
            }
            TokenKind::Eof => {
                push_trimmed(&mut statements, sql.get(start..).unwrap_or(""));
            }
            _ => {}
        }

match self {
            ParseError::UnexpectedEof { span } | ParseError::Unexpected { span, .. } => *span,
        }

match self {
            ParseError::UnexpectedEof { span } => {
                write!(
                    f,
                    "unexpected end of query at {}:{}",
                    span.line, span.column
                )
            }
            ParseError::Unexpected { message, span } => {
                write!(
                    f,
                    "unexpected token at {}:{}: {message}",
                    span.line, span.column
                )
            }
        }

match expr {
        Expr::Column(name) => resolve_ident(name, aliases),
        Expr::Literal(_) => {}
        Expr::BinaryOp(lhs, _, rhs) => {
            resolve_expr_aliases(lhs, aliases);
            resolve_expr_aliases(rhs, aliases);
        }
        Expr::Not(inner) => resolve_expr_aliases(inner, aliases),
        Expr::Neg(inner) => resolve_expr_aliases(inner, aliases),
        Expr::IsNull { expr, .. } => resolve_expr_aliases(expr, aliases),
        // A subquery has its own FROM/alias scope -- its column refs are
        // resolved when *it* is converted, not against the outer query's
        // aliases.
        Expr::InSubquery { expr, .. } => resolve_expr_aliases(expr, aliases),
    }

match lit {
        AstLiteral::Integer(n) => Literal::Int(*n),
        AstLiteral::Float(f) => Literal::Float(*f),
        AstLiteral::Str(s) => Literal::Str(s.clone()),
        other => return Err(unsupported(span, format!("literal {other:?}"))),
    }

match &expr.kind {
        ExprKind::Column {
            table: None,
            catalog: None,
            name,
        } => Ok(name.clone()),
        ExprKind::Column {
            table: Some(table),
            catalog: None,
            name,
        } => Ok(format!("{table}.{name}")),
        ExprKind::Column {
            catalog: Some(_), ..
        } => Err(unsupported(expr.span, "catalog-qualified column".into())),
        other => Err(unsupported(
            expr.span,
            format!("expected a column reference, found {other:?}"),
        )),
    }

match args {
        FunctionArgs::Star => {
            if agg != AggFunc::Count {
                return Err(unsupported(expr.span, "only COUNT supports (*)".into()));
            }
            Ok(format!("{}(*)", agg.name()))
        }
        FunctionArgs::List(list) => match list.as_slice() {
            [one] => Ok(format!("{}({})", agg.name(), column_name(one)?)),
            _ => Err(unsupported(
                expr.span,
                "an aggregate takes exactly one column or *".into(),
            )),
        },
    }

match list.as_slice() {
            [one] => Ok(format!("{}({})", agg.name(), column_name(one)?)),
            _ => Err(unsupported(
                expr.span,
                "an aggregate takes exactly one column or *".into(),
            )),
        }

match &expr.kind {
        ExprKind::Literal(lit) => Ok(Expr::Literal(ast_literal(lit, expr.span)?)),
        ExprKind::Column { .. } => Ok(Expr::Column(column_name(expr)?)),
        ExprKind::Unary {
            op: UnaryOp::Not,
            expr: inner,
        } => Ok(Expr::Not(Box::new(convert_expr(inner)?))),
        ExprKind::Unary {
            op: UnaryOp::Minus,
            expr: inner,
        } => Ok(Expr::Neg(Box::new(convert_expr(inner)?))),
        // Unary `+` is a no-op, same as the old grammar (which discarded a
        // leading `+` instead of representing it at all).
        ExprKind::Unary {
            op: UnaryOp::Plus,
            expr: inner,
        } => convert_expr(inner),
        ExprKind::Unary { op, .. } => Err(unsupported(expr.span, format!("unary operator {op:?}"))),
        // `expr IS [NOT] NULL` parses as `Is{lhs, rhs: NULL literal,
        // negated}` in row's grammar, not a dedicated `IsNull` node (that
        // variant exists for the historical SQLite `IS`/`IS NOT` operator
        // between two arbitrary expressions, which this subset doesn't
        // support otherwise).
        ExprKind::Is { lhs, rhs, negated }
            if matches!(rhs.kind, ExprKind::Literal(AstLiteral::Null)) =>
        {
            Ok(Expr::IsNull {
                expr: Box::new(convert_expr(lhs)?),
                negated: *negated,
            })
        }
        ExprKind::Binary { op, lhs, rhs } => Ok(Expr::BinaryOp(
            Box::new(convert_expr(lhs)?),
            ast_binop(*op, expr.span)?,
            Box::new(convert_expr(rhs)?),
        )),
        ExprKind::IsNull {
            expr: inner,
            negated,
        } => Ok(Expr::IsNull {
            expr: Box::new(convert_expr(inner)?),
            negated: *negated,
        }),
        ExprKind::Paren(inner) => convert_expr(inner),
        ExprKind::InSubquery {
            expr: inner,
            subquery,
            negated: false,
        } => Ok(Expr::InSubquery {
            expr: Box::new(convert_expr(inner)?),
            subquery: Box::new(convert_select(subquery)?),
        }),
        ExprKind::InSubquery { negated: true, .. } => {
            Err(unsupported(expr.span, "NOT IN (SELECT ...)".into()))
        }
        other => Err(unsupported(
            expr.span,
            format!("unsupported expression form {other:?}"),
        )),
    }

match &expr.kind {
        ExprKind::Binary {
            op: AstBinOp::Eq,
            lhs,
            rhs,
        } => Ok((column_name(lhs)?, column_name(rhs)?)),
        _ => Err(unsupported(expr.span, "JOIN ON must be col = col".into())),
    }

match col {
        ResultColumn::Star => Ok(SelectItem::Star),
        ResultColumn::TableStar { .. } => Err(unsupported(
            Span::UNKNOWN,
            "table.* is not supported".into(),
        )),
        ResultColumn::Expr {
            expr,
            alias: Some(_),
        } => Err(unsupported(
            expr.span,
            "column alias (AS) is not supported".into(),
        )),
        ResultColumn::Expr { expr, alias: None } => match &expr.kind {
            ExprKind::Column { .. } => Ok(SelectItem::Column(column_name(expr)?)),
            ExprKind::FunctionCall {
                name,
                distinct,
                args,
                over: Some(window_def),
            } => {
                if *distinct {
                    return Err(unsupported(
                        expr.span,
                        "DISTINCT inside a window function".into(),
                    ));
                }
                convert_window_call(expr.span, name, args, window_def)
            }
            ExprKind::FunctionCall {
                name,
                distinct,
                args,
                over: None,
            } => {
                if *distinct {
                    return Err(unsupported(
                        expr.span,
                        "DISTINCT inside an aggregate".into(),
                    ));
                }
                let agg = AggFunc::from_name(name)
                    .ok_or_else(|| unsupported(expr.span, format!("unknown function {name}")))?;
                let arg = match args {
                    FunctionArgs::Star => {
                        if agg != AggFunc::Count {
                            return Err(unsupported(expr.span, "only COUNT supports (*)".into()));
                        }
                        None
                    }
                    FunctionArgs::List(list) => match list.as_slice() {
                        [one] => Some(column_name(one)?),
                        _ => {
                            return Err(unsupported(
                                expr.span,
                                "an aggregate takes exactly one column or *".into(),
                            ))
                        }
                    },
                };
                Ok(SelectItem::Agg(agg, arg))
            }
            _ => Err(unsupported(
                expr.span,
                "unsupported SELECT expression".into(),
            )),
        },
    }

match &expr.kind {
            ExprKind::Column { .. } => Ok(SelectItem::Column(column_name(expr)?)),
            ExprKind::FunctionCall {
                name,
                distinct,
                args,
                over: Some(window_def),
            } => {
                if *distinct {
                    return Err(unsupported(
                        expr.span,
                        "DISTINCT inside a window function".into(),
                    ));
                }
                convert_window_call(expr.span, name, args, window_def)
            }
            ExprKind::FunctionCall {
                name,
                distinct,
                args,
                over: None,
            } => {
                if *distinct {
                    return Err(unsupported(
                        expr.span,
                        "DISTINCT inside an aggregate".into(),
                    ));
                }
                let agg = AggFunc::from_name(name)
                    .ok_or_else(|| unsupported(expr.span, format!("unknown function {name}")))?;
                let arg = match args {
                    FunctionArgs::Star => {
                        if agg != AggFunc::Count {
                            return Err(unsupported(expr.span, "only COUNT supports (*)".into()));
                        }
                        None
                    }
                    FunctionArgs::List(list) => match list.as_slice() {
                        [one] => Some(column_name(one)?),
                        _ => {
                            return Err(unsupported(
                                expr.span,
                                "an aggregate takes exactly one column or *".into(),
                            ))
                        }
                    },
                };
                Ok(SelectItem::Agg(agg, arg))
            }
            _ => Err(unsupported(
                expr.span,
                "unsupported SELECT expression".into(),
            )),
        }

match args {
                    FunctionArgs::Star => {
                        if agg != AggFunc::Count {
                            return Err(unsupported(expr.span, "only COUNT supports (*)".into()));
                        }
                        None
                    }
                    FunctionArgs::List(list) => match list.as_slice() {
                        [one] => Some(column_name(one)?),
                        _ => {
                            return Err(unsupported(
                                expr.span,
                                "an aggregate takes exactly one column or *".into(),
                            ))
                        }
                    },
                }

match list.as_slice() {
                        [one] => Some(column_name(one)?),
                        _ => {
                            return Err(unsupported(
                                expr.span,
                                "an aggregate takes exactly one column or *".into(),
                            ))
                        }
                    }

match (func.is_niladic(), args) {
        (true, FunctionArgs::List(list)) if list.is_empty() => (None, None),
        (true, _) => Err(unsupported(span, format!("{name} takes no arguments")))?,
        (false, FunctionArgs::Star) => {
            if func != WindowFunc::Count {
                return Err(unsupported(span, "only COUNT supports (*)".into()));
            }
            (None, None)
        }
        (false, FunctionArgs::List(list)) if matches!(func, WindowFunc::Lag | WindowFunc::Lead) => {
            match list.as_slice() {
                [one] => (Some(column_name(one)?), None),
                [one, offset_expr] => {
                    let offset = match &offset_expr.kind {
                        ExprKind::Literal(AstLiteral::Integer(n)) => *n,
                        _ => {
                            return Err(unsupported(offset_expr.span, "non-integer offset".into()))
                        }
                    };
                    (Some(column_name(one)?), Some(offset))
                }
                _ => return Err(unsupported(span, format!("{name} takes 1 or 2 arguments"))),
            }
        }
        (false, FunctionArgs::List(list)) => match list.as_slice() {
            [one] => (Some(column_name(one)?), None),
            _ => {
                return Err(unsupported(
                    span,
                    "a window function takes exactly one column or *".into(),
                ))
            }
        },
    }

match list.as_slice() {
                [one] => (Some(column_name(one)?), None),
                [one, offset_expr] => {
                    let offset = match &offset_expr.kind {
                        ExprKind::Literal(AstLiteral::Integer(n)) => *n,
                        _ => {
                            return Err(unsupported(offset_expr.span, "non-integer offset".into()))
                        }
                    };
                    (Some(column_name(one)?), Some(offset))
                }
                _ => return Err(unsupported(span, format!("{name} takes 1 or 2 arguments"))),
            }

match list.as_slice() {
            [one] => (Some(column_name(one)?), None),
            _ => {
                return Err(unsupported(
                    span,
                    "a window function takes exactly one column or *".into(),
                ))
            }
        }

match &j.constraint {
            Some(JoinConstraint::On(expr)) => extract_equi_join(expr)?,
            Some(JoinConstraint::Using(_)) => {
                return Err(unsupported(j.table.span, "USING join".into()))
            }
            None if kind == JoinKind::Cross => (String::new(), String::new()),
            None => return Err(unsupported(j.table.span, "join without ON".into())),
        }

match select.order_by.first() {
        Some(OrderingTerm {
            nulls_last: Some(_),
            ..
        }) => return Err(unsupported(select.span, "NULLS FIRST/LAST".into())),
        Some(OrderingTerm { expr, desc, .. }) => {
            let column = match &expr.kind {
                ExprKind::Column { .. } => column_name(expr)?,
                ExprKind::FunctionCall {
                    name,
                    distinct,
                    args,
                    over: None,
                } => aggregate_call_label(expr, name, *distinct, args)?,
                _ => {
                    return Err(unsupported(
                        expr.span,
                        format!(
                            "expected a column reference or aggregate, found {:?}",
                            expr.kind
                        ),
                    ))
                }
            };
            Some(OrderBy {
                column,
                descending: desc.unwrap_or(false),
            })
        }
        None => None,
    }

match &expr.kind {
                ExprKind::Column { .. } => column_name(expr)?,
                ExprKind::FunctionCall {
                    name,
                    distinct,
                    args,
                    over: None,
                } => aggregate_call_label(expr, name, *distinct, args)?,
                _ => {
                    return Err(unsupported(
                        expr.span,
                        format!(
                            "expected a column reference or aggregate, found {:?}",
                            expr.kind
                        ),
                    ))
                }
            }

match &select.limit {
        Some(l) => {
            if l.offset.is_some() {
                return Err(unsupported(select.span, "LIMIT OFFSET".into()));
            }
            match &l.limit.kind {
                ExprKind::Literal(AstLiteral::Integer(n)) if *n >= 0 => Some(*n as usize),
                _ => return Err(unsupported(l.limit.span, "non-integer LIMIT".into())),
            }
        }
        None => None,
    }

match &l.limit.kind {
                ExprKind::Literal(AstLiteral::Integer(n)) if *n >= 0 => Some(*n as usize),
                _ => return Err(unsupported(l.limit.span, "non-integer LIMIT".into())),
            }

match crate::parser::row::parse_select(input) {
        ParseOutcome::Accepted(select) => convert_select(&select),
        ParseOutcome::Unsupported { message, span } | ParseOutcome::Invalid { message, span } => {
            Err(from_outcome(message, span))
        }
    }

match crate::parser::row::parse_explain(input) {
        ParseOutcome::Accepted(explain) => {
            let form = if explain.query_plan {
                Explain::QueryPlan
            } else {
                Explain::Opcodes
            };
            Ok((form, convert_select(&explain.select)?))
        }
        ParseOutcome::Unsupported { message, span } | ParseOutcome::Invalid { message, span } => {
            Err(from_outcome(message, span))
        }
    }

match self {
            PlanError::UnknownColumn(name) => write!(f, "unknown column: {name}"),
            PlanError::UnsupportedSemiJoin(msg) => write!(f, "unsupported semi-join: {msg}"),
            PlanError::UnsupportedJoinKind(kind) => write!(
                f,
                "join kind {kind:?} is not yet executable (only Inner/Left are implemented)"
            ),
            PlanError::StarWithAggregation => write!(
                f,
                "SELECT * cannot be combined with GROUP BY, an aggregate, or a window function"
            ),
        }

match lit {
        Literal::Int(v) => Value::Int(*v),
        Literal::Float(v) => Value::Float(*v),
        Literal::Str(v) => Value::Str(v.clone().into()),
    }

match expr {
        Expr::Column(name) => ctx.load_column(name),
        Expr::Literal(lit) => {
            let reg = ctx.alloc();
            ctx.push(Opcode::LoadConst {
                reg,
                value: literal_value(lit),
            });
            reg
        }
        Expr::InSubquery { .. } => {
            // `compile_semi_join` handles `IN (subquery)` itself and strips
            // it from `where_clause` before ever calling `compile` --
            // reaching this arm means `IN (subquery)` was used via the
            // regular single-table path, which can't run a subquery.
            // Compile to an always-false predicate (no rows) rather than
            // panicking.
            let reg = ctx.alloc();
            ctx.push(Opcode::LoadConst {
                reg,
                value: Value::Bool(false),
            });
            reg
        }
        Expr::BinaryOp(lhs, op, rhs) => {
            let a = compile_expr(lhs, ctx);
            let b = compile_expr(rhs, ctx);
            let dst = ctx.alloc();
            ctx.push(Opcode::Map {
                dst,
                op: map_bin_op(*op),
                a,
                b,
            });
            dst
        }
        Expr::Not(inner) => {
            let a = compile_expr(inner, ctx);
            let dst = ctx.alloc();
            ctx.push(Opcode::Map {
                dst,
                op: MapOp::Not,
                a,
                b: a,
            });
            dst
        }
        Expr::Neg(inner) => {
            let a = compile_expr(inner, ctx);
            let dst = ctx.alloc();
            ctx.push(Opcode::Map {
                dst,
                op: MapOp::Neg,
                a,
                b: a,
            });
            dst
        }
        Expr::IsNull { expr, negated } => {
            let a = compile_expr(expr, ctx);
            let dst = ctx.alloc();
            ctx.push(Opcode::Map {
                dst,
                op: if *negated {
                    MapOp::IsNotNull
                } else {
                    MapOp::IsNull
                },
                a,
                b: a,
            });
            dst
        }
    }

match item {
            SelectItem::Agg(_, Some(name)) => {
                agg_srcs.push(ctx.load_column(name));
            }
            // Plain projected columns are emitted (not aggregated), but they
            // must be loaded here for the same reason as the keys above: a
            // column first loaded below the Filter keeps its full pre-filter
            // length while the filtered registers shrink, and Emit then
            // indexes past the end of the short ones. `load_column` memoizes,
            // so the projection code further down reuses these registers
            // instead of emitting a second LoadColumn.
            SelectItem::Column(name) if query.group_by.is_empty() => {
                ctx.load_column(name);
                agg_srcs.push(0);
            }
            _ => agg_srcs.push(0),
        }

match func {
                AggFunc::Avg => {
                    let sum_dst = ctx.alloc();
                    let count_dst = ctx.alloc();
                    aggs.push((AggFunc::Sum, src));
                    agg_dst.push(sum_dst);
                    aggs.push((AggFunc::Count, src));
                    agg_dst.push(count_dst);
                    agg_parts.push(AggPart::Avg(emit_regs.len(), emit_regs.len() + 1));
                    emit_regs.push(sum_dst);
                    emit_regs.push(count_dst);
                }
                other => {
                    let dst = ctx.alloc();
                    aggs.push((*other, src));
                    agg_dst.push(dst);
                    agg_parts.push(match other {
                        AggFunc::Sum => AggPart::Sum,
                        AggFunc::Count => AggPart::Count,
                        AggFunc::Min => AggPart::Min,
                        AggFunc::Max => AggPart::Max,
                        AggFunc::Avg => unreachable!(),
                    });
                    emit_regs.push(dst);
                }
            }

match prefix {
            None => left_columns.push(name.clone()),
            Some(p) if p == query.from => left_columns.push(name.clone()),
            Some(p) if p == join.table => right_columns.push(name.clone()),
            Some(_) => return Err(PlanError::UnknownColumn(name.clone())),
