            Ok(if found {
                Step::Jump(to_pc(instr.p2))
            } else {
                Step::Next
            })
        }
        Opcode::NoConflict => {
            let (key, collations) = key_from_registers(vm, "NoConflict", instr.p3, &instr.p4)?;
            let cursor = vm.cursor_mut(instr.p1)?;
            // Ephemeral index (DISTINCT / IN-subquery): membership of the
