        Value::Real(r) => Value::Integer(real_to_i64(r)),
        _ => Value::Integer(0), // unreachable: coerce_text_to_numeric only returns Integer/Real
    }

match value {
        Value::Real(_) => value.clone(),
        #[allow(clippy::cast_precision_loss)]
        Value::Integer(i) => Value::Real(*i as f64),
        Value::Text(s) => real_from_numeric(coerce_text_to_numeric(s)),
        Value::Blob(bytes) => {
            real_from_numeric(coerce_text_to_numeric(&String::from_utf8_lossy(bytes)))
        }
        Value::Null => Value::Null,
    }

match numeric {
        Value::Real(r) => Value::Real(r),
        #[allow(clippy::cast_precision_loss)]
        Value::Integer(i) => Value::Real(i as f64),
        _ => Value::Real(0.0), // unreachable: coerce_text_to_numeric only returns Integer/Real
    }

match value {
        Value::Integer(_) | Value::Real(_) => value.clone(),
        Value::Text(s) => downgrade_whole_reals(coerce_text_to_numeric(s)),
        Value::Blob(bytes) => {
            downgrade_whole_reals(coerce_text_to_numeric(&String::from_utf8_lossy(bytes)))
        }
        Value::Null => Value::Null,
    }

match numeric {
        Value::Real(r) if r.fract() == 0.0 && r.is_finite() && in_i64_range(r) => {
            Value::Integer(real_to_i64(r))
        }
        other => other,
    }

match self {
            AggregateError::Unknown { name } => write!(f, "no such aggregate function: {name}"),
            AggregateError::IntegerOverflow => write!(f, "integer overflow"),
        }

match arg {
        None | Some(Value::Null) => None,
        Some(v @ (Value::Integer(_) | Value::Real(_))) => Some(v.clone()),
        Some(Value::Text(s)) => Some(coerce_text_to_numeric(s)),
        Some(Value::Blob(b)) => Some(coerce_text_to_numeric(&String::from_utf8_lossy(b))),
    }

match name.to_ascii_lowercase().as_str() {
            "count" => Ok(AggState::Count(0)),
            "sum" => Ok(AggState::Sum {
                int_total: 0,
                real_total: 0.0,
                saw_real: false,
                saw_any: false,
            }),
            "avg" => Ok(AggState::Avg {
                int_total: 0,
                real_total: 0.0,
                saw_real: false,
                count: 0,
            }),
            "min" => Ok(AggState::Min(None)),
            "max" => Ok(AggState::Max(None)),
            other => Err(AggregateError::Unknown {
                name: other.to_string(),
            }),
        }

match state {
        Some(s) => s,
        None => AggState::initial(name)?,
    }

match &mut state {
        AggState::Count(n) => {
            if args.first().is_none_or(|v| !matches!(v, Value::Null)) {
                *n = n.saturating_add(1);
            }
        }
        AggState::Sum {
            int_total,
            real_total,
            saw_real,
            saw_any,
        } => match numeric_arg(args.first()) {
            None => {}
            Some(Value::Integer(i)) => {
                *saw_any = true;
                if *saw_real {
                    *real_total += i as f64;
                } else {
                    *int_total = int_total.saturating_add(i128::from(i));
                }
            }
            Some(Value::Real(r)) => {
                *saw_any = true;
                if !*saw_real {
                    *real_total += *int_total as f64;
                    *int_total = 0;
                    *saw_real = true;
                }
                *real_total += r;
            }
            Some(Value::Null | Value::Text(_) | Value::Blob(_)) => {}
        },
        AggState::Avg {
            int_total,
            real_total,
            saw_real,
            count,
        } => match numeric_arg(args.first()) {
            None => {}
            Some(Value::Integer(i)) => {
                *count = count.saturating_add(1);
                if *saw_real {
                    *real_total += i as f64;
                } else {
                    *int_total = int_total.saturating_add(i128::from(i));
                }
            }
            Some(Value::Real(r)) => {
                *count = count.saturating_add(1);
                if !*saw_real {
                    *real_total += *int_total as f64;
                    *int_total = 0;
                    *saw_real = true;
                }
                *real_total += r;
            }
            Some(Value::Null | Value::Text(_) | Value::Blob(_)) => {}
        },
        AggState::Min(current) => {
            if let Some(v) = args.first().filter(|v| !matches!(v, Value::Null)) {
                if current
                    .as_ref()
                    .is_none_or(|c| compare(v, c, collation) == Ordering::Less)
                {
                    *current = Some(v.clone());
                }
            }
        }
        AggState::Max(current) => {
            if let Some(v) = args.first().filter(|v| !matches!(v, Value::Null)) {
                if current
                    .as_ref()
                    .is_none_or(|c| compare(v, c, collation) == Ordering::Greater)
                {
                    *current = Some(v.clone());
                }
            }
        }
    }

match numeric_arg(args.first()) {
            None => {}
            Some(Value::Integer(i)) => {
                *saw_any = true;
                if *saw_real {
                    *real_total += i as f64;
                } else {
                    *int_total = int_total.saturating_add(i128::from(i));
                }
            }
            Some(Value::Real(r)) => {
                *saw_any = true;
                if !*saw_real {
                    *real_total += *int_total as f64;
                    *int_total = 0;
                    *saw_real = true;
                }
                *real_total += r;
            }
            Some(Value::Null | Value::Text(_) | Value::Blob(_)) => {}
        }

match numeric_arg(args.first()) {
            None => {}
            Some(Value::Integer(i)) => {
                *count = count.saturating_add(1);
                if *saw_real {
                    *real_total += i as f64;
                } else {
                    *int_total = int_total.saturating_add(i128::from(i));
                }
            }
            Some(Value::Real(r)) => {
                *count = count.saturating_add(1);
                if !*saw_real {
                    *real_total += *int_total as f64;
                    *int_total = 0;
                    *saw_real = true;
                }
                *real_total += r;
            }
            Some(Value::Null | Value::Text(_) | Value::Blob(_)) => {}
        }

match state {
        None => match name.to_ascii_lowercase().as_str() {
            "count" => Ok(Value::Integer(0)),
            "sum" | "avg" | "min" | "max" => Ok(Value::Null),
            other => Err(AggregateError::Unknown {
                name: other.to_string(),
            }),
        },
        Some(AggState::Count(n)) => Ok(Value::Integer(*n)),
        Some(AggState::Sum {
            int_total,
            real_total,
            saw_real,
            saw_any,
        }) => {
            if !saw_any {
                return Ok(Value::Null);
            }
            #[allow(clippy::cast_precision_loss)]
            if *saw_real {
                Ok(Value::Real(*real_total + *int_total as f64))
            } else {
                i64::try_from(*int_total)
                    .map(Value::Integer)
                    .map_err(|_| AggregateError::IntegerOverflow)
            }
        }
        Some(AggState::Avg {
            int_total,
            real_total,
            saw_real,
            count,
        }) => {
            if *count == 0 {
                return Ok(Value::Null);
            }
            #[allow(clippy::cast_precision_loss)]
            let total = if *saw_real {
                *real_total + *int_total as f64
            } else {
                *int_total as f64
            };
            #[allow(clippy::cast_precision_loss)]
            Ok(Value::Real(total / *count as f64))
        }
        Some(AggState::Min(v)) | Some(AggState::Max(v)) => Ok(v.clone().unwrap_or(Value::Null)),
    }

match name.to_ascii_lowercase().as_str() {
            "count" => Ok(Value::Integer(0)),
            "sum" | "avg" | "min" | "max" => Ok(Value::Null),
            other => Err(AggregateError::Unknown {
                name: other.to_string(),
            }),
        }

match v {
        Value::Null => 0,
        Value::Integer(_) | Value::Real(_) => 1,
        Value::Text(_) => 2,
        Value::Blob(_) => 3,
    }

match (x.is_nan(), y.is_nan()) {
        (true, true) => Ordering::Equal,
        (true, false) => Ordering::Greater,
        (false, true) => Ordering::Less,
        (false, false) => x.partial_cmp(&y).unwrap_or(Ordering::Equal),
    }

match self.pos {
            Some(0) | None => {
                self.pos = None;
                false
            }
            Some(p) => {
                self.pos = Some(p - 1);
                true
            }
        }

match idx.filter(|&idx| idx < self.rows.len()) {
            Some(idx) => {
                self.pos = Some(idx);
                true
            }
            None => {
                self.pos = None;
                false
            }
        }

match rowid {
            Some(rowid) => {
                self.current_rowid = Some(rowid);
                self.at_row = true;
                true
            }
            None => {
                self.at_row = false;
                false
            }
        }

match (v, collation) {
            (Value::Text(s), Collation::NoCase) => {
                Value::Text(Rc::from(s.to_ascii_lowercase().as_str()))
            }
            (Value::Text(s), Collation::RTrim) => Value::Text(Rc::from(s.trim_end_matches(' '))),
            _ => v.clone(),
        }

match (a, b) {
        (Value::Null, Value::Null) => Ordering::Equal,
        (Value::Null, _) => {
            if key.nulls_first {
                Ordering::Less
            } else {
                Ordering::Greater
            }
        }
        (_, Value::Null) => {
            if key.nulls_first {
                Ordering::Greater
            } else {
                Ordering::Less
            }
        }
        _ => {
            let ord = super::compare::compare(a, b, key.collation);
            if key.descending {
                ord.reverse()
            } else {
                ord
            }
        }
    }

match self.find_group(&key_values) {
            Some(idx) => idx,
            None => {
                self.groups.push(GroupSlot {
                    row: blob,
                    key_values,
                    accumulators: Vec::new(),
                });
                self.groups.len() - 1
            }
        }

match self.pos {
            Some(0) | None => {
                self.pos = None;
                false
            }
            Some(p) => {
                self.pos = Some(p - 1);
                true
            }
        }

match self.entries.get(pos) {
            Some((k, _)) if compare_keys(k, key, &self.key_cols) == std::cmp::Ordering::Equal => {
                self.pos = Some(pos);
                true
            }
            _ => {
                self.pos = None;
                false
            }
        }

match self.rows.iter().position(|(r, _)| *r == rowid) {
                Some(pos) => {
                    self.pos = Some(pos);
                    true
                }
                None => {
                    self.pos = None;
                    false
                }
            }

match self {
            RecordError::UnexpectedEof { offset } => {
                write!(f, "unexpected end of input at byte offset {offset}")
            }
            RecordError::HeaderTooShort {
                declared,
                varint_len,
            } => write!(
                f,
                "record header length {declared} is shorter than its own header-length varint ({varint_len} bytes)"
            ),
            RecordError::HeaderOverrun { offset, header_len } => write!(
                f,
                "record header entry at offset {offset} extends past the declared header length {header_len}"
            ),
            RecordError::TrailingData { trailing } => write!(
                f,
                "record has {trailing} unconsumed trailing byte(s) after decoding all columns"
            ),
            RecordError::InvalidUtf8 => write!(f, "invalid UTF-8 in text value"),
            RecordError::InvalidUtf16 => write!(f, "invalid UTF-16 in text value"),
        }

match encoding {
        TextEncoding::Utf8 => s.len(),
        TextEncoding::Utf16Le | TextEncoding::Utf16Be => s.encode_utf16().count().saturating_mul(2),
    }

match encoding {
        TextEncoding::Utf8 => out.extend_from_slice(s.as_bytes()),
        TextEncoding::Utf16Le => {
            out.extend(s.encode_utf16().flat_map(|u| u.to_le_bytes()));
        }
        TextEncoding::Utf16Be => {
            out.extend(s.encode_utf16().flat_map(|u| u.to_be_bytes()));
        }
    }

match value {
        Value::Null => (0, 0),
        Value::Integer(i) => {
            let st = integer_serial_type(*i);
            (st, integer_body_len(st))
        }
        Value::Real(_) => (7, 8),
        Value::Blob(b) => (blob_serial_type(b.len()), b.len()),
        Value::Text(s) => {
            let len = encoded_text_len(s, encoding);
            (text_serial_type(len), len)
        }
    }

match value {
        Value::Null => {}
        Value::Integer(i) => write_integer_body_into(*i, serial_type, out),
        Value::Real(r) => out.extend_from_slice(&r.to_be_bytes()),
        Value::Blob(b) => out.extend_from_slice(b),
        Value::Text(s) => write_text_body_into(s, encoding, out),
    }

match e {
        RecordError::UnexpectedEof { offset } => RecordError::UnexpectedEof {
            offset: pos.saturating_add(offset),
        },
        other => other,
    }

match serial_type {
        0 => Ok((Value::Null, 0)),
        1 => {
            let [b0] = take_array(buf, pos)?;
            Ok((Value::Integer(i64::from(b0 as i8)), 1))
        }
        2 => {
            let b = take_array(buf, pos)?;
            Ok((Value::Integer(i64::from(i16::from_be_bytes(b))), 2))
        }
        3 => {
            let [b0, b1, b2] = take_array(buf, pos)?;
            let mut v = (i64::from(b0) << 16) | (i64::from(b1) << 8) | i64::from(b2);
            if b0 & 0x80 != 0 {
                v = v.wrapping_sub(1 << 24); // sign-extend 24-bit
            }
            Ok((Value::Integer(v), 3))
        }
        4 => {
            let b = take_array(buf, pos)?;
            Ok((Value::Integer(i64::from(i32::from_be_bytes(b))), 4))
        }
        5 => {
            let bytes: [u8; 6] = take_array(buf, pos)?;
            let [b0, ..] = bytes;
            let mut v: i64 = 0;
            for byte in bytes {
                v = (v << 8) | i64::from(byte);
            }
            if b0 & 0x80 != 0 {
                v = v.wrapping_sub(1 << 48); // sign-extend 48-bit
            }
            Ok((Value::Integer(v), 6))
        }
        6 => {
            let b = take_array(buf, pos)?;
            Ok((Value::Integer(i64::from_be_bytes(b)), 8))
        }
        7 => {
            let b = take_array(buf, pos)?;
            let value = f64::from_be_bytes(b);
            // A NaN float payload decodes as NULL, matching SQLite's
            // sqlite3VdbeSerialGet.
            if value.is_nan() {
                Ok((Value::Null, 8))
            } else {
                Ok((Value::Real(value), 8))
            }
        }
        8 => Ok((Value::Integer(0), 0)),
        9 => Ok((Value::Integer(1), 0)),
        // Types 10/11 are reserved/internal and never appear in a
        // well-formed database, but decode as NULL rather than erroring.
        10 | 11 => Ok((Value::Null, 0)),
        n if n % 2 == 0 => {
            let len = (n.wrapping_sub(12) / 2) as usize;
            let bytes = take(buf, pos, len)?;
            Ok((Value::Blob(bytes.into()), len))
        }
        n => {
            let len = (n.wrapping_sub(13) / 2) as usize;
            let bytes = take(buf, pos, len)?;
            let text = decode_text(bytes, encoding)?;
            Ok((Value::Text(text), len))
        }
    }

match entries.get(idx) {
        Some(&(serial_type, offset)) => {
            let (value, _) = decode_serial_value(serial_type, payload, offset, encoding)?;
            Ok(value)
        }
        None => Ok(Value::Null),
    }

match literal.parse::<i64>() {
        Ok(i) => Value::Integer(i),
        Err(_) => literal
            .parse::<f64>()
            .map_or(Value::Integer(0), Value::Real),
    }

match v {
        Value::Integer(_) | Value::Real(_) => v.clone(),
        Value::Text(s) => coerce_text_to_numeric(s),
        Value::Null | Value::Blob(_) => Value::Integer(0),
    }

match v {
        Value::Integer(i) => *i as f64,
        Value::Real(r) => *r,
        _ => 0.0,
    }

match (as_numeric(a), as_numeric(b)) {
        (Value::Integer(x), Value::Integer(y)) => match int_op(x, y) {
            Some(v) => Value::Integer(v),
            None => Value::Real(float_op(x as f64, y as f64)),
        },
        (x, y) => Value::Real(float_op(to_f64(&x), to_f64(&y))),
    }

match int_op(x, y) {
            Some(v) => Value::Integer(v),
            None => Value::Real(float_op(x as f64, y as f64)),
        }

match (as_numeric(a), as_numeric(b)) {
        (Value::Integer(_), Value::Integer(0)) => Value::Null,
        (Value::Integer(x), Value::Integer(y)) => match x.checked_div(y) {
            Some(v) => Value::Integer(v),
            None => Value::Real(x as f64 / y as f64),
        },
        (x, y) => {
            let (x, y) = (to_f64(&x), to_f64(&y));
            if y == 0.0 {
                Value::Null
            } else {
                Value::Real(x / y)
            }
        }
    }

match x.checked_div(y) {
            Some(v) => Value::Integer(v),
            None => Value::Real(x as f64 / y as f64),
        }

match v {
        Value::Integer(i) => *i,
        Value::Real(r) => r.trunc() as i64,
        Value::Text(s) => match coerce_text_to_numeric(s) {
            Value::Integer(i) => i,
            Value::Real(r) => r.trunc() as i64,
            _ => 0,
        },
        Value::Null | Value::Blob(_) => 0,
    }

match coerce_text_to_numeric(s) {
            Value::Integer(i) => i,
            Value::Real(r) => r.trunc() as i64,
            _ => 0,
        }

match checked_add(&max, &Value::Integer(1)) {
            Value::Real(r) => assert!((r - 9_223_372_036_854_775_808.0).abs() < 1.0),
            other => panic!("expected REAL promotion, got {other:?}"),
        }

match checked_mul(&max, &Value::Integer(2)) {
            Value::Real(r) => assert!(r > i64::MAX as f64),
            other => panic!("expected REAL promotion, got {other:?}"),
        }

match (agg_parts.is_empty() && !distinct, order_by, limit) {
        (true, Some((col, descending)), Some(limit)) => run_parallel_top_n(
            segments,
            &body,
            &TopN {
                col: *col,
                descending: *descending,
                limit: *limit,
            },
        )?,
        _ => run_parallel(segments, &body)?,
    }

match index.get(&key_str) {
                Some(&i) => merge_rows(agg_parts, &mut groups[i].1, &row),
                None => {
                    index.insert(key_str, groups.len());
                    groups.push((key, row));
                }
            }

match part {
            AggPart::GroupKey => {}
            AggPart::Sum | AggPart::Count => {
                into[i] =
                    Value::Float(into[i].as_f64().unwrap_or(0.0) + from[i].as_f64().unwrap_or(0.0));
            }
            AggPart::Min => {
                if let (Some(a), Some(b)) = (into[i].as_f64(), from[i].as_f64()) {
                    into[i] = Value::Float(a.min(b));
                } else if matches!(into[i], Value::Null) {
                    into[i] = from[i].clone();
                }
            }
            AggPart::Max => {
                if let (Some(a), Some(b)) = (into[i].as_f64(), from[i].as_f64()) {
                    into[i] = Value::Float(a.max(b));
                } else if matches!(into[i], Value::Null) {
                    into[i] = from[i].clone();
                }
            }
            AggPart::Avg(_, _) => {}
        }

match part {
            AggPart::Avg(sum_i, count_i) => {
                let (sum, count) = (
                    row[*sum_i].as_f64().unwrap_or(0.0),
                    row[*count_i].as_f64().unwrap_or(0.0),
                );
                out.push(if count == 0.0 {
                    Value::Null
                } else {
                    Value::Float(sum / count)
                });
                skip = Some(*count_i);
            }
            _ => out.push(row[i].clone()),
        }

match &expr {
            Expr::BinaryOp(lhs, op, rhs) => {
                assert_eq!(**lhs, Expr::Column("a".into()));
                assert_eq!(*op, BinOp::Gt);
                assert_eq!(**rhs, Expr::Literal(Literal::Int(5)));
            }
            _ => panic!("expected BinaryOp"),
        }

match &expr {
            Expr::InSubquery {
                expr: inner_expr,
                subquery,
            } => {
                assert_eq!(**inner_expr, Expr::Column("customer_id".into()));
                assert_eq!(**subquery, inner);
            }
            _ => panic!("expected InSubquery"),
        }

match collation {
        Collation::Binary => a.as_bytes().cmp(b.as_bytes()),
        Collation::NoCase => a
            .as_bytes()
            .iter()
            .map(u8::to_ascii_lowercase)
            .cmp(b.as_bytes().iter().map(u8::to_ascii_lowercase)),
        Collation::RTrim => {
            let a = a.trim_end_matches(' ');
            let b = b.trim_end_matches(' ');
            a.as_bytes().cmp(b.as_bytes())
        }
    }

match self {
            EmitError::Parse(e) => write!(f, "{e}"),
            EmitError::Unsupported(what) => write!(f, "codegen does not support {what} yet"),
        }

match &instruction.comment {
            Some(comment) => {
                let _ = writeln!(
                    out,
                    "    {}, // {}",
                    render_opcode(&instruction.opcode),
                    comment.replace('\n', " ")
                );
            }
            None => {
                let _ = writeln!(out, "    {},", render_opcode(&instruction.opcode));
            }
        }

match order_by {
        Some((pos, desc)) => format!("Some(({pos}, {desc}))"),
        None => "None".to_string(),
    }

match item {
        SelectItem::Column(name) => {
            format!("SelectItem::Column({}.to_string())", rust_str_literal(name))
        }
        SelectItem::Star => "SelectItem::Star".to_string(),
        SelectItem::Agg(func, arg) => format!(
            "SelectItem::Agg(AggFunc::{}, {})",
            render_agg_func(*func),
            render_option_string(arg.as_deref())
        ),
        SelectItem::Window(spec) => {
            format!("SelectItem::Window({})", render_window_spec(spec))
        }
    }

match s {
        Some(s) => format!("Some({}.to_string())", rust_str_literal(s)),
        None => "None".to_string(),
    }

match lit {
        Literal::Int(v) => format!("Literal::Int({v})"),
        Literal::Float(v) => format!("Literal::Float({v:?})"),
        Literal::Str(v) => format!("Literal::Str({}.to_string())", rust_str_literal(v)),
    }

match expr {
        Some(e) => format!("Some({})", render_expr(e)),
        None => "None".to_string(),
    }

match ob {
        Some(OrderBy { column, descending }) => format!(
            "Some(OrderBy {{ column: {}.to_string(), descending: {descending} }})",
            rust_str_literal(column)
        ),
        None => "None".to_string(),
    }

match op {
        Opcode::LoadColumn { reg, column } => format!(
            "Opcode::LoadColumn {{ reg: {reg}, column: std::borrow::Cow::Borrowed({}) }}",
            rust_str_literal(column)
        ),
        Opcode::LoadConst { reg, value } => format!(
            "Opcode::LoadConst {{ reg: {reg}, value: {} }}",
            render_value(value)
        ),
        Opcode::Map { dst, op, a, b } => format!(
            "Opcode::Map {{ dst: {dst}, op: MapOp::{}, a: {a}, b: {b} }}",
            render_map_op(*op)
        ),
        Opcode::Filter { predicate } => format!("Opcode::Filter {{ predicate: {predicate} }}"),
        Opcode::Reduce { func, src, dst } => format!(
            "Opcode::Reduce {{ func: AggFunc::{}, src: {}, dst: {dst} }}",
            render_agg_func(*func),
            render_option_usize(*src)
        ),
        Opcode::GroupReduce {
            group_by,
            aggs,
            agg_dst,
        } => {
            let group_by = render_usize_slice(group_by);
            let agg_dst = render_usize_slice(agg_dst);
            let aggs: Vec<String> = aggs
                .iter()
                .map(|(f, s)| {
                    format!(
                        "(AggFunc::{}, {})",
                        render_agg_func(*f),
                        render_option_usize(*s)
                    )
                })
                .collect();
            format!("Opcode::GroupReduce {{ group_by: std::borrow::Cow::Borrowed(&{group_by}), aggs: std::borrow::Cow::Borrowed(&[{}]), agg_dst: std::borrow::Cow::Borrowed(&{agg_dst}) }}", aggs.join(", "))
        }
        Opcode::Scan => "Opcode::Scan".to_string(),
        Opcode::Emit { registers } => format!(
            "Opcode::Emit {{ registers: std::borrow::Cow::Borrowed(&{}) }}",
            render_usize_slice(registers)
        ),
        Opcode::NextSegment { loop_start } => {
            format!("Opcode::NextSegment {{ loop_start: {loop_start} }}")
        }
        Opcode::Halt => "Opcode::Halt".to_string(),
        Opcode::Finalize {
            agg_parts,
            num_group_keys,
            distinct,
            order_by,
            limit,
        } => {
            let parts: Vec<String> = agg_parts.iter().map(render_agg_part).collect();
            format!(
                "Opcode::Finalize {{ agg_parts: std::borrow::Cow::Borrowed(&[{}]), num_group_keys: {num_group_keys}, distinct: {distinct}, order_by: {}, limit: {} }}",
                parts.join(", "),
                render_order_by(*order_by),
                render_option_usize(*limit)
            )
        }
        // No caller-side planner emits these three yet -- the join/semi-
        // join/window bypass shapes ([`render_joined`]/
        // [`render_semi_join`]/[`render_windowed`]) still reconstruct a
        // `Query` literal instead of a `const PROGRAM` for those cases
        // (see this module's top doc comment), so no flat program this
        // module renders contains them. Not a feature gap to silently
        // paper over with a fake rendering: once a real planner starts
        // emitting these, this arm should become a real render_*
        // implementation at that point, not before.
        Opcode::HashBuild { .. } | Opcode::HashProbe { .. } | Opcode::Window { .. } => {
            unreachable!("no planner feeding emit::batch emits {op:?} yet")
        }
    }

match value {
        Value::Int(v) => format!("Value::Int({v})"),
        Value::Float(v) => format!("Value::Float({v:?})"),
        Value::Bool(v) => format!("Value::Bool({v})"),
        Value::Str(v) => format!(
            "Value::Str(std::borrow::Cow::Borrowed({}))",
            rust_str_literal(v)
        ),
        Value::Null => "Value::Null".to_string(),
    }
